@js:
var SBOX = [], INV = [];
var gm = function (a, b) {
    var p = 0, i, h;
    a &= 255; b &= 255;
    for (i = 0; i < 8; i++) { if (b & 1) p ^= a; h = a & 128; a = (a << 1) & 255; if (h) a ^= 27; b >>= 1; }
    return p & 255;
};
var rl = function (x, n) { return ((x << n) | (x >> (8 - n))) & 255; };
(function () {
    var a, v, inv;
    for (a = 0; a < 256; a++) {
        inv = 0;
        if (a) { for (v = 1; v < 256; v++) { if (gm(a, v) === 1) { inv = v; break; } } }
        SBOX[a] = (inv ^ rl(inv, 1) ^ rl(inv, 2) ^ rl(inv, 3) ^ rl(inv, 4) ^ 99) & 255;
    }
    for (a = 0; a < 256; a++) INV[SBOX[a]] = a;
})();
var expandKey = function (key) {
    var w = [], i, j, t, rcon = 1;
    for (i = 0; i < 4; i++) w[i] = [key[4 * i], key[4 * i + 1], key[4 * i + 2], key[4 * i + 3]];
    for (i = 4; i < 44; i++) {
        t = w[i - 1].slice();
        if (i % 4 === 0) {
            t = [t[1], t[2], t[3], t[0]];
            t = [SBOX[t[0]], SBOX[t[1]], SBOX[t[2]], SBOX[t[3]]];
            t[0] ^= rcon;
            rcon = gm(rcon, 2);
        }
        w[i] = [];
        for (j = 0; j < 4; j++) w[i][j] = w[i - 4][j] ^ t[j];
    }
    return w;
};
var addRK = function (s, w, r) {
    var c, rr, k;
    for (c = 0; c < 4; c++) { k = w[r * 4 + c]; for (rr = 0; rr < 4; rr++) s[rr + 4 * c] ^= k[rr]; }
};
var invShiftRows = function (s) {
    var t = s.slice(), r, c;
    for (r = 1; r < 4; r++) for (c = 0; c < 4; c++) s[r + 4 * c] = t[r + 4 * ((c - r + 4) % 4)];
};
var invSubBytes = function (s) { for (var i = 0; i < 16; i++) s[i] = INV[s[i]]; };
var invMixColumns = function (s) {
    var c, a0, a1, a2, a3;
    for (c = 0; c < 4; c++) {
        a0 = s[4 * c]; a1 = s[4 * c + 1]; a2 = s[4 * c + 2]; a3 = s[4 * c + 3];
        s[4 * c] = gm(a0, 14) ^ gm(a1, 11) ^ gm(a2, 13) ^ gm(a3, 9);
        s[4 * c + 1] = gm(a0, 9) ^ gm(a1, 14) ^ gm(a2, 11) ^ gm(a3, 13);
        s[4 * c + 2] = gm(a0, 13) ^ gm(a1, 9) ^ gm(a2, 14) ^ gm(a3, 11);
        s[4 * c + 3] = gm(a0, 11) ^ gm(a1, 13) ^ gm(a2, 9) ^ gm(a3, 14);
    }
};
var decBlock = function (blk, w) {
    var s = blk.slice(), r;
    addRK(s, w, 10);
    for (r = 9; r >= 1; r--) { invShiftRows(s); invSubBytes(s); addRK(s, w, r); invMixColumns(s); }
    invShiftRows(s); invSubBytes(s); addRK(s, w, 0);
    return s;
};
var aesDec = function (data, keyBytes, ivBytes) {
    var w = expandKey(keyBytes), out = [], off, i, prev = ivBytes.slice(), s;
    for (off = 0; off + 16 <= data.length; off += 16) {
        s = decBlock(data.slice(off, off + 16), w);
        for (i = 0; i < 16; i++) out.push(s[i] ^ prev[i]);
        prev = data.slice(off, off + 16);
    }
    return out;
};
var b64 = function (s) {
    var cs = "ABCDEFGHIJKLMNOPQRSTUVWXYZabcdefghijklmnopqrstuvwxyz0123456789+/";
    var out = [], i, c, v, buf = 0, bits = 0;
    s = String(s);
    for (i = 0; i < s.length; i++) {
        c = s.charAt(i);
        if (c === "=") break;
        v = cs.indexOf(c);
        if (v < 0) continue;
        buf = ((buf << 6) | v) & 0xffffff;
        bits += 6;
        if (bits >= 8) { bits -= 8; out.push((buf >> bits) & 255); }
    }
    return out;
};
var u8 = function (b) {
    var out = "", i = 0, x, y, z, q, cp;
    while (i < b.length) {
        x = b[i++];
        if (x < 0x80) out += String.fromCharCode(x);
        else if (x < 0xe0) { y = b[i++]; out += String.fromCharCode(((x & 31) << 6) | (y & 63)); }
        else if (x < 0xf0) { y = b[i++]; z = b[i++]; out += String.fromCharCode(((x & 15) << 12) | ((y & 63) << 6) | (z & 63)); }
        else {
            y = b[i++]; z = b[i++]; q = b[i++];
            cp = ((((x & 7) << 18) | ((y & 63) << 12) | ((z & 63) << 6) | (q & 63)) - 0x10000);
            out += String.fromCharCode(0xd800 + (cp >> 10), 0xdc00 + (cp & 1023));
        }
    }
    return out;
};
var s = String(src);
var m = s.match(/booktxthtml'\)\.html\(x\(\s*"([^"]+)"\s*,\s*"([^"]+)"\s*,\s*"([^"]+)"\s*\)\)/);
