while ((match = regex.exec(html)) != null) {
  categories.push({
    url: match[1],
    title: match[2],
    count: parseInt(match[5], 10),
    style: {
      "layout_flexBasisPercent": 0.25,
      "layout_flexGrow": 1
    }
  });
}

JSON.stringify(categories);

